   112|async function fetchJson(url: string, opts?: RequestInit): Promise<Record<string, unknown>> {
   113|  const maxRetries = 3;
   114|  let lastErr: Error | null = null;
   115|  for (let attempt = 0; attempt < maxRetries; attempt++) {
   116|    try {
